const DIP=-2.5; // alert if 24h drop is <= -2.5%
const j=$json; const btc=Number(j.bitcoin?.usd_24h_change), eth=Number(j.ethereum?.usd_24h_change);
return [{json:{
  dip: (isFinite(btc)&&btc<=DIP) || (isFinite(eth)&&eth<=DIP),
  text:`Dip Alert — BTC ${btc?.toFixed?.(2)}%, ETH ${eth?.toFixed?.(2)}%`
}}];
